using MediatR;using ProjectNet.Application.Abstractions;using ProjectNet.Application.DTOs;namespace ProjectNet.Application.Queries.GetProductById;public sealed class GetProductByIdQueryHandler : IRequestHandler<GetProductByIdQuery, ProductDto?> { private readonly IProductRepository _r; public GetProductByIdQueryHandler(IProductRepository r)=>_r=r; public async Task<ProductDto?> Handle(GetProductByIdQuery request, CancellationToken ct){ var p=await _r.GetByIdAsync(request.Id,ct); return p?.ToDto(); } }
